package playground.sns;
import org.springframework.context.annotation.*; import org.springframework.security.config.Customizer; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.*; import org.springframework.security.crypto.password.*; import org.springframework.security.provisioning.*; import org.springframework.security.web.*;
@Configuration public class SecurityConfig { @Bean PasswordEncoder encoder(){return new BCryptPasswordEncoder();} @Bean UserDetailsService users(PasswordEncoder e){return new InMemoryUserDetailsManager(User.withUsername("yuki").password(e.encode("playground")).roles("USER").build());} @Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("GET","/posts").permitAll().anyRequest().authenticated()).httpBasic(Customizer.withDefaults()).build();}}
